/**
 * Values inlined from `.env` by `react-native-dotenv` at build time. Every
 * entry is optional: a checkout without `.env` still compiles and runs on the
 * documented defaults (see `src/app/config.ts` and `.env.example`).
 */
declare module '@env' {
  export const USDA_API_KEY: string | undefined;
  export const APP_CONTACT_EMAIL: string | undefined;
}
